import{printedArtwork}from'../../modeling/artwork.js';import{spec}from'./dimensions.js';const sources={front:new URL('./source-vector-front.png',import.meta.url).href,back:new URL('./source-vector-back.png',import.meta.url).href};export function addStickers(host){const result=[];for(const face of Object.keys(host.cat1CnAssembly.labels)){const v=spec.labels[face],position=[...v.position];if(face==='front')position[2]+=.08;result.push(...printedArtwork(host,{target:host.cat1CnAssembly.labels[face],url:sources[face],size:v.size,position,face,depth:.12,name:'Cat1-CN own U204 '+face+' source raster',artworkKind:'source-vector-raster'})??[]);}return result;}
